Total: "+result.total+"
Average: "+result.average.toFixed(2)+"
Status: "+(result.average>=75?"Passed":"Failed")+"
Highest: "+result.highest+"
Lowest: "+result.lowest;document.getElementById("output").textContent=text;console.log(text);}catch(error){document.getElementById("output").textContent=error.message;}}
document.getElementById("grade-form").addEventListener("submit",event=>{event.preventDefault();calculate();});
calculate();

